using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioSharedViewportProbe {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static int phase,sample;static bool capture;static long previous;static double deadline;static Dictionary<string,List<double>> values=new Dictionary<string,List<double>>();static StringBuilder report=new StringBuilder();
 static Quaternion initialRotation;static Vector3 initialPivot;static float initialSize;static string Label=>phase==0?"uncached.rotate":phase==1?"cached.rotate":"nohandle.gpu";
 static void Add(string name,double value){if(!values.TryGetValue(name,out var list))values[name]=list=new List<double>();list.Add(value);}
 static void Stage(string name){if(!capture)return;long now=Stopwatch.GetTimestamp();if(name!="scene.start")Add(Label+"."+name,(now-previous)*1000d/Stopwatch.Frequency);previous=now;}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{
 StudioHandleFrameValidation.Validate();report.AppendLine("PASS handle-frame unit assertions="+StudioHandleFrameValidation.Checks);var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var doc=StudioModelDocument.Import(model,"Assets/SharedViewportProbe.asset");controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);view.position=new Rect(0,0,1500,950);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);int n=editor.Document.nodes.FindIndex(x=>x.name=="Body"&&x.mesh);editor.SelectObject(n);typeof(StudioModelEditor).GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);typeof(StudioModelEditor).GetField("local",F).SetValue(editor,false);editor.Components.UnionWith(Enumerable.Range(0,editor.ActiveMesh.vertexCount));editor.Frame(view);initialRotation=view.rotation;initialPivot=view.pivot;initialSize=view.size;StudioModelEditor.SceneProfileStage=Stage;report.AppendLine("Body vertices="+editor.ActiveMesh.vertexCount+" selected="+editor.Components.Count+" pipeline="+(GraphicsSettings.currentRenderPipeline?.name??"Built-in")+" device="+SystemInfo.graphicsDeviceType);deadline=EditorApplication.timeSinceStartup+2;EditorApplication.update+=Tick;
 }catch(Exception e){Finish(e);}}
 static void Send(EventType type){view.SendEvent(new Event{type=type,modifiers=EventModifiers.Alt,mousePosition=new Vector2(700,400)});}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{
 if(sample==0){typeof(StudioModelEditor).GetField("tool",F).SetValue(editor,phase<2?Tool.Rotate:Tool.None);editor.ForceLegacyVertexMarkers=false;editor.DisableHandleFrameCache=phase==0;view.LookAtDirect(initialPivot,initialRotation,initialSize);typeof(StudioModelEditor).GetMethod("ClearComponentDrawing",F).Invoke(editor,null);}
 typeof(MashBoxStudioViewport).GetField("navigating",F).SetValue(view,true);view.ApplyStudioNavigation(StudioShortcut.Orbit,new Vector2(.4f,.1f));view.MarkDirty(MashBoxStudioViewport.DirtyState.Camera);capture=sample>=10;var watch=Stopwatch.StartNew();Send(EventType.Layout);double layout=watch.Elapsed.TotalMilliseconds;watch.Restart();Send(EventType.Repaint);double repaint=watch.Elapsed.TotalMilliseconds;if(capture){Add(Label+".layout",layout);Add(Label+".repaint",repaint);Add(Label+".combined",layout+repaint);}capture=false;
 if(++sample<40)return;sample=0;if(++phase<3)return;Finish(null);
 }catch(Exception e){Finish(e);}}
 static void Finish(Exception error){EditorApplication.update-=Tick;StudioModelEditor.SceneProfileStage=null;if(error!=null)report.AppendLine(error.ToString());foreach(var pair in values){var s=pair.Value.OrderBy(x=>x).ToArray();report.AppendLine(pair.Key+" median_ms="+s[s.Length/2].ToString("F4")+" p95_ms="+s[(int)Math.Ceiling(s.Length*.95)-1].ToString("F4"));}report.AppendLine(error==null?"PASS bounded camera-state/native Layout+Repaint probe; not physical input FPS":"FAIL");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../viewport-shared-probe-result.txt")),report.ToString());if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.Exit(error==null?0:1);}
}